    "hero_badge": "ലൈവ് വോയ്‌സ്-ടു-വോയ്‌സ് പ്രവർത്തനക്ഷമമാക്കി",
    "hero_title_1": "പൗരന്മാരെ ശാക്തീകരിക്കുന്നു",
    "hero_title_2": "AI-അധിഷ്ഠിത പദ്ധതി അന്വേഷണത്തിലൂടെ",
    "hero_desc": "സർക്കാർ ക്ഷേമപദ്ധതികളുടെ സങ്കീർണ്ണതകൾ മനസ്സിലാക്കാൻ സേവാ-ബോട്ട് നിങ്ങളെ സഹായിക്കുന്നു. സെക്കൻഡുകൾക്കുള്ളിൽ നിങ്ങളുടെ ആവശ്യങ്ങൾക്കനുസരിച്ചുള്ള സ്കോളർഷിപ്പുകൾ, സബ്‌സിഡികൾ, സേവനങ്ങൾ എന്നിവ കണ്ടെത്തുക. തത്സമയ സംഭാഷണത്തിനായി ഞങ്ങളുടെ പുതിയ ലൈവ് വോയ്‌സ് ചാറ്റ് പരീക്ഷിക്കുക.",
    "hero_btn_live": "ലൈവ് വോയ്‌സ് ചാറ്റ് പരീക്ഷിക്കുക",
    "hero_btn_standard": "സ്റ്റാൻഡേർഡ് ചാറ്റ്",
    "about_title": "പൗരന്മാരും ആനുകൂല്യങ്ങളും തമ്മിലുള്ള അകലം കുറയ്ക്കുന്നു",
    "about_desc": "ഇന്ത്യയിലെ പല സർക്കാർ പദ്ധതികളും പൗരന്മാർക്ക് അവയെക്കുറിച്ച് അറിയാത്തതുകൊണ്ടോ അപേക്ഷാ നടപടികൾ ബുദ്ധിമുട്ടായതുകൊണ്ടോ ഉപയോഗിക്കപ്പെടാതെ പോകുന്നു. ഈ വിവര അസമത്വം പരിഹരിക്കാനാണ് സേവാ-ബോട്ട് സൃഷ്ടിച്ചിരിക്കുന്നത്.",
    "about_item_1": "ലളിതമായ പ്രകൃതിഭാഷാ തിരയൽ",
    "about_item_2": "എല്ലാ വിഭാഗക്കാർക്കുമായി തരംതിരിച്ച പദ്ധതികൾ",
    "about_item_3": "ഘട്ടം ഘട്ടമായുള്ള അപേക്ഷാ മാർഗ്ഗനിർദ്ദേശങ്ങൾ",
    "about_item_4": "അടിയന്തിര സഹായത്തിനായി 24/7 ലഭ്യമാണ്",
    "about_item_5": "ലഭ്യതയ്ക്കായി വോയ്‌സ്-ടു-വോയ്‌സ് പിന്തുണ",
    "features_title": "എന്തുകൊണ്ട് സേവാ-ബോട്ട് തിരഞ്ഞെടുക്കണം?",
    "features_subtitle": "ഓരോ പൗരനും തടസ്സമില്ലാത്ത അനുഭവം നൽകുന്നതിന് നൂതന AI സാങ്കേതികവിദ്യ പൊതുസേവനവുമായി ഒത്തുചേരുന്നു.",
    "feature_1_title": "തൽക്ഷണ AI തിരയൽ",
    "feature_1_desc": "ഇനി അവസാനമില്ലാത്ത PDF ലിസ്റ്റുകൾ സ്ക്രോൾ ചെയ്യേണ്ടതില്ല. സേവാ-ബോട്ടിനോട് ചോദിക്കൂ, ഉടൻ തന്നെ ശരിയായ പദ്ധതി കണ്ടെത്തൂ.",
    "feature_2_title": "ബഹുഭാഷാ പിന്തുണ",
    "feature_2_desc": "നിങ്ങൾക്കിഷ്ടമുള്ള ഭാഷയിൽ സംവദിക്കുക. സേവാ-ബോട്ട് വിവിധ ഭാഷാ ആവശ്യങ്ങൾ മനസ്സിലാക്കുകയും പ്രതികരിക്കുകയും ചെയ്യുന്നു.",
    "feature_3_title": "ലൈവ് വോയ്‌സ് ചാറ്റ്",
    "feature_3_desc": "സേവാ-ബോട്ട് ലൈവിലൂടെ തത്സമയ, കുറഞ്ഞ കാലതാമസമുള്ള വോയ്‌സ് സംഭാഷണങ്ങൾ അനുഭവിക്കുക.",
