    "hero_badge": "நேரடி குரல்-க்கு-குரல் இயக்கப்பட்டது",
    "hero_title_1": "குடிமக்களை மேம்படுத்துதல்",
    "hero_title_2": "AI-மூலம் திட்டங்களைக் கண்டறிதல்",
    "hero_desc": "அரசு நலத்திட்டங்களின் சிக்கலான நிலப்பரப்பை வழிநடத்த சேவா-பாட் உங்களுக்கு உதவுகிறது. உங்கள் தேவைகளுக்கு ஏற்ப உதவித்தொகைகள், மானியங்கள் மற்றும் சேவைகளை நொடிகளில் கண்டறியவும். நிகழ்நேர உரையாடலுக்கு எங்கள் புதிய நேரடி குரல் அரட்டையை முயற்சிக்கவும்.",
    "hero_btn_live": "நேரடி குரல் அரட்டையை முயற்சிக்கவும்",
    "hero_btn_standard": "நிலையான அரட்டை",
    "about_title": "குடிமக்களுக்கும் நன்மைகளுக்கும் இடையிலான இடைவெளியைக் குறைத்தல்",
    "about_desc": "இந்தியாவில் பல அரசுத் திட்டங்கள் குடிமக்களுக்கு அவற்றைப் பற்றித் தெரியாததாலோ அல்லது விண்ணப்ப செயல்முறை கடினமாக இருப்பதாலோ பயன்படுத்தப்படாமல் போகின்றன. இந்த தகவல் சமச்சீரற்ற தன்மையைத் தீர்க்க சேவா-பாட் உருவாக்கப்பட்டது.",
    "about_item_1": "எளிமைப்படுத்தப்பட்ட இயற்கை மொழி தேடல்",
    "about_item_2": "அனைத்து மக்களுக்கும் வகைப்படுத்தப்பட்ட திட்டங்கள்",
