    "about_item_5": "அணுகலுக்கான குரல்-க்கு-குரல் ஆதரவு",
    "features_title": "ஏன் சேவா-பாட்டைத் தேர்ந்தெடுக்க வேண்டும்?",
    "features_subtitle": "மேம்பட்ட AI தொழில்நுட்பம் ஒவ்வொரு குடிமகனுக்கும் தடையற்ற அனுபவத்தை வழங்க பொதுச் சேவையைச் சந்திக்கிறது.",
    "feature_1_title": "உடனடி AI தேடல்",
