    "feature_2_title": "பல்மொழி ஆதரவு",
    "feature_2_desc": "உங்களுக்கு விருப்பமான மொழியில் உரையாடுங்கள். சேவா-பாட் பல்வேறு மொழித் தேவைகளைப் புரிந்துகொண்டு பதிலளிக்கிறது.",
    "feature_3_title": "நேரடி குரல் அரட்டை",
