    "footer_desc": "சேவா-பாட் என்பது இந்தியாவின் ஒவ்வொரு குடிமகனுக்கும் அரசு நலத்திட்டங்களுக்கான அணுகலை எளிதாக்குவதற்கான AI-ஆற்றல் கொண்ட முன்முயற்சியாகும். தகவல் மூலம் தேசத்தை மேம்படுத்துதல்.",
