    "chat_translated_to": "{lang} மொழியில் மொழிபெயர்க்கப்பட்டது",
    "initial_message": "நமஸ்தே! நான் சேவா-பாட். இன்று அரசுத் திட்டங்களைக் கண்டறிய நான் உங்களுக்கு எப்படி உதவுவது? உதவித்தொகைகள், விவசாய மானியங்கள் அல்லது ஸ்டார்ட்அப் நன்மைகள் பற்றி நீங்கள் என்னிடம் கேட்கலாம். விண்ணப்ப செயல்முறை மற்றும் தேவையான ஆவணங்கள் குறித்தும் நான் விளக்க முடியும்.",
