    "about_desc": "ভাৰতৰ বহুতো চৰকাৰী আঁচনি ব্যৱহাৰ নোহোৱাকৈ থাকে কাৰণ নাগৰিকসকলে সেইবোৰৰ বিষয়ে নাজানে বা আবেদন প্ৰক্ৰিয়াটো কঠিন বুলি ভাবে। এই তথ্যৰ অসমতা দূৰ কৰিবলৈ সেৱাবট সৃষ্টি কৰা হৈছিল।",
