    "initial_message": "ਨਮਸਤੇ! ਮੈਂ ਸੇਵਾ-ਬੋਟ ਹਾਂ। ਮੈਂ ਅੱਜ ਤੁਹਾਨੂੰ ਸਰਕਾਰੀ ਸਕੀਮਾਂ ਦੀ ਖੋਜ ਕਰਨ ਵਿੱਚ ਕਿਵੇਂ ਮਦਦ ਕਰ ਸਕਦਾ ਹਾਂ? ਤੁਸੀਂ ਮੈਨੂੰ ਸਕਾਲਰਸ਼ਿਪਾਂ, ਕਿਸਾਨ ਸਬਸਿਡੀਆਂ ਜਾਂ ਸਟਾਰਟਅੱਪ ਲਾਭਾਂ ਬਾਰੇ ਪੁੱਛ ਸਕਦੇ ਹੋ। ਮੈਂ ਅਰਜ਼ੀ ਦੀ ਪ੍ਰਕਿਰਿਆ ਅਤੇ ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ਾਂ ਬਾਰੇ ਵੀ ਦੱਸ ਸਕਦਾ ਹਾਂ।",
