    "hero_desc": "सेवा-बॉट तुसगी सरकारी कल्याण दे जटिल परिदृश्य च मदद करदा ऐ। सैकंडें च अपनी जरूरतें दे मताबक स्कॉलरशिप, सब्सिडी ते सेवाएं लब्भो। रियल-टाइम गल्लबात लेई साडी नवीं लाइव वॉइस चैट आजमाओ।",
