    "hero_desc": "सेवाबोटआ नोंथांखौ सरकारि मोजां मोननायनि गोब्राब थासारियाव मदद खालामो। सेकेण्डफोरनि गेजेराव नोंथांनि गोनांथि बादियै फरायसावृथि, हाबिला आरो सिबिथायफोर नागिरना मोन। जोंनि गोदान लाइभ भोइस च्याटखौ रीयल-टाइम रायलायनो थाखाय नाजादो।",
