    "hero_badge": "ಲೈವ್ ವಾಯ್ಸ್-ಟು-ವಾಯ್ಸ್ ಸಕ್ರಿಯ",
    "hero_title_1": "ನಾಗರಿಕೆರೆನ್ ಸಬಲೀಕರಣ ಮಲ್ಪುನ",
    "hero_title_2": "AI-ಚಾಲಿತ ಯೋಜನೆ ನಾಡುನ ಒಟ್ಟುಗು",
    "hero_desc": "ಸೇವಾಬೋಟ್ ಸರ್ಕಾರಿ ಕಲ್ಯಾಣದ ಕಷ್ಟದ ಪರಿಸ್ಥಿತಿಡ್ ನಿಕ್ಲೆಗ್ ಸಹಾಯ ಮಲ್ಪುಂಡು. ಸೆಕೆಂಡ್‌ಲೆಡ್ ನಿಕ್ಲೆನ ಅಗತ್ಯೊಗು ತಕ್ಕಂತೆ ಸ್ಕಾಲರ್‌ಶಿಪ್, ಸಬ್ಸಿಡಿ ಬೊಕ್ಕ ಸೇವೆಲೆನ್ ನಾಡ್ಲೆ. ರಿಯಲ್-ಟೈಮ್ ಪಾತೆರೊಗು ನಮ್ಮ ಪೊಸ ಲೈವ್ ವಾಯ್ಸ್ ಚಾಟ್ ಪ್ರಯತ್ನ ಮಲ್ಪುಲೆ.",
    "hero_btn_live": "ಲೈವ್ ವಾಯ್ಸ್ ಚಾಟ್ ಪ್ರಯತ್ನ ಮಲ್ಪುಲೆ",
    "hero_btn_standard": "ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಚಾಟ್",
    "about_title": "ನಾಗರಿಕೆರ್ ಬೊಕ್ಕ ಪ್ರಯೋಜನೊಲೆನ ನಡುತ ಅಂತರೊನು ಕಮ್ಮಿ ಮಲ್ಪುನ",
    "about_desc": "ಭಾರತೊಡು ಮಸ್ತ್ ಸರ್ಕಾರಿ ಯೋಜನೆಲು ನಾಗರಿಕೆರೆಗ್ ಗೊತ್ತಿಜ್ಜಂದೆ ಅತ್ತಂಡ ಅರ್ಜಿ ಪಾಡುನ ಕ್ರಿಯೆ ಕಷ್ಟ ಪಂಡ್‌ದ್ ಬಳಕೆ ಆವಂದೆ ಒರಿದ್ ಪೋಪುಂಡು. ಈ ಮಾಹಿತಿ ಅಸಮಾನತೆನ್ ದೂರ ಮಲ್ಪೆರೆ ಸೇವಾಬೋಟ್ ತಯಾರ್ ಮಲ್ತ್‌ದಿನವು.",
    "about_item_1": "ಸರಳವಾಯಿನ ನೈಸರ್ಗಿಕ ಭಾಷೆ ನಾಡುನ",
    "about_item_2": "ಮಾತಾ ಜನಸಂಖ್ಯೆಗ್ ವರ್ಗೀಕರಿಸಿನ ಯೋಜನೆಲು",
    "about_item_3": "ಹಂತ-ಹಂತದ ಅರ್ಜಿ ಮಾರ್ಗದರ್ಶನ",
