    "about_item_5": "ಸುಲಭವಾದ್ ತಿಕ್ಕರೆ ವಾಯ್ಸ್-ಟು-ವಾಯ್ಸ್ ಬೆಂಬಲ",
    "features_title": "ಸೇವಾಬೋಟ್ ದಾಯೆ ಆಯ್ಕೆ ಮಲ್ಪೊಡು?",
    "features_subtitle": "ಪ್ರತಿ ನಾಗರಿಕೆರೆಗ್ ಒಂಜಿ ಎಡ್ಡೆ ಅನುಭವ ಕೊರಿಯೆರೆ ಸುಧಾರಿತ AI ತಂತ್ರಜ್ಞಾನ ಸಾರ್ವಜನಿಕ ಸೇವೆದೊಟ್ಟುಗು ಸೇರ್ದ್ಂಡ್.",
    "feature_1_title": "ತಕ್ಷಣದ AI ನಾಡುನ",
    "feature_1_desc": "ಇತ್ತೆ ಮುಗಿಯಂದಿನ PDF ಪಟ್ಟಿಲೆನ್ ಸ್ಕ್ರೋಲ್ ಮಲ್ಪುನ ಅಗತ್ಯ ಇಜ್ಜಿ. ಬರೆ ಸೇವಾಬೋಟ್‌ಗ್ ಕೇನ್ಲೆ ಬೊಕ್ಕ ತಕ್ಷಣ ಸರಿಯಾಯಿನ ಯೋಜನೆನ್ ಪಡೆಯಿರಿ.",
    "feature_2_title": "ಬಹುಭಾಷಾ ಬೆಂಬಲ",
    "feature_2_desc": "ನಿಕ್ಲೆಗ್ ಇಷ್ಟವಾಯಿನ ಭಾಷೆಡ್ ಪಾತೆರಿಲೆ. ಸೇವಾಬೋಟ್ ಬೇತೆ ಬೇತೆ ಭಾಷೆದ ಅಗತ್ಯೊಲೆನ್ ಅರ್ಥ ಮಲ್ತೊನುಂಡು ಬೊಕ್ಕ ಪ್ರತಿಕ್ರಿಯೆ ಕೊರ್ಪುಂಡು.",
    "feature_3_title": "ಲೈವ್ ವಾಯ್ಸ್ ಚಾಟ್",
    "feature_3_desc": "ಸೇವಾಬೋಟ್ ಲೈವ್ ಒಟ್ಟುಗು ರಿಯಲ್-ಟೈಮ್, ಕಮ್ಮಿ ತಡ ಆಪಿನ ವಾಯ್ಸ್ ಪಾತೆರದ ಅನುಭವ ಪಡೆಯಿರಿ.",
